export function segmentHash(symbol: string, segment: TranscriptSegment): string {
  return sha256Hex(`${symbol}|${segment.startSec}|${segment.text}`);
}

export function inCallWindow(callTimeMs: number | null, nowMs: number, preMinutes: number, postMinutes: number): boolean {
  if (callTimeMs === null) return false;
  return nowMs >= callTimeMs - preMinutes * 60_000 && nowMs <= callTimeMs + postMinutes * 60_000;
}

export function sessionNeedsRefresh(refreshedAtMs: number | null, nowMs: number): boolean {
  return refreshedAtMs === null || nowMs < refreshedAtMs || nowMs - refreshedAtMs >= SESSION_REFRESH_MS;
}

export function eventDateOf(callTimeMs: number | null): string {
  return callTimeMs === null ? "unscheduled" : new Date(callTimeMs).toISOString().slice(0, 10);
}

export interface GuidanceAlert {
  dedupKey: string;
  symbol: string;
  kind: "earnings_guidance";
  severity: "critical";
  payload: Record<string, unknown>;
}

/**
 * One alert per guidance field and value. The dedup key contains the value, so a repeated poll is a no-op, and a changed
 * number is a new alert. Alerts are only built inside a call window (the caller decides), so an out-of-window
 * smoke test can store rows without paging anyone.
 */
export function buildGuidanceAlerts(input: {
  symbol: string;
  googleSymbol: string;
  eventDate: string;
  fetchedAt: string;
  findings: GuidanceFindings;
}): GuidanceAlert[] {
  return GUIDANCE_FIELDS.flatMap((field) => {
    const finding = input.findings[field];
    if (!finding) return [];
    return [
      {
        dedupKey: `earnings:${input.symbol}:${input.eventDate}:${field}:${finding.value}`,
        symbol: input.symbol,
        kind: "earnings_guidance" as const,
        severity: "critical" as const,
        payload: {
          source: "google-finance-earnings",
          google_symbol: input.googleSymbol,
          field,
          value: finding.value,
          evidence: finding.evidence,
          event_date: input.eventDate,
          event_ts: input.fetchedAt,
          source_url: quoteEarningsUrl(input.googleSymbol),
        },
      },
    ];
  });
}
